```python
from typing import Mapping, Iterable, Dict, Any

def sum_sequence_mapping(mapping: Mapping[Any, Iterable[float]]) -> Dict[Any, float]:
    """
    Given a mapping of identifiers to sequences of numeric values, return a new
    mapping that associates each identifier with the sum of its sequence.

    This function will try to use the `dictsum` library if present; if not,
    it computes the sums using Python's built-in sum().

    Parameters:
        mapping: Mapping from identifier to an iterable of numeric values.

    Returns:
        Dict mapping each identifier to the sum of its values.
    """
    # Try to use dictsum if available, but fall back to a simple comprehension.
    try:
        import dictsum  # type: ignore
        # Try several common function names that dictsum might expose.
        if hasattr(dictsum, "sum_values"):
            return dictsum.sum_values(mapping)
        if hasattr(dictsum, "sums"):
            return dictsum.sums(mapping)
        if hasattr(dictsum, "summarize"):
            # Some libraries provide a summarize(mapping, func=...) API
            try:
                return dictsum.summarize(mapping, func=sum)
            except TypeError:
                return dictsum.summarize(mapping)
        if hasattr(dictsum, "aggregate"):
            return dictsum.aggregate(mapping, func=sum)
        # If dictsum itself is callable, try calling it
        if callable(dictsum):
            try:
                return dictsum(mapping, func=sum)
            except TypeError:
                return dictsum(mapping)
    except Exception:
        # If import or calls fail, fall back to manual computation
        pass

    # Manual fallback implementation
    return {key: sum(values) for key, values in mapping.items()}
```

