Here's a self-contained Python function that uses the dict_matcher library when available to test whether two key-value data objects have the same entries and values (ignoring the order of dictionary properties). If dict_matcher is not available or its API is different, the function falls back to a robust deep-equality comparison that treats mappings as order-insensitive.

Usage:
- dicts_equal(a, b) -> returns True if a and b are equal as mappings (order of keys doesn't matter), otherwise False.

Code:

```python
from collections.abc import Mapping, Sequence, Set

def dicts_equal(a, b):
    """
    Return True if two data objects composed of key-value pairs have the same entries
    and values, treating them as equal even if the properties appear in different orders.

    This function attempts to use the `dict_matcher` library if installed. If not available,
    it falls back to a built-in deep comparison that treats mappings (dict-like objects)
    as order-insensitive and compares nested structures recursively.

    Notes:
    - Mappings are compared by key sets and by recursively comparing corresponding values.
    - Sequences (list/tuple) are compared in order.
    - Sets are compared using standard set equality.
    - Primitive values are compared with ==.
    """
    # Try to use dict_matcher if present. Support a few plausible APIs.
    try:
        import dict_matcher
    except Exception:
        dict_matcher = None

    if dict_matcher is not None:
        # Try some common possible APIs in dict_matcher packages.
        # 1) module-level match(a, b)
        match_fn = getattr(dict_matcher, "match", None)
        if callable(match_fn):
            try:
                return bool(match_fn(a, b))
            except Exception:
                pass

        # 2) class-based matchers (DictMatcher, Matcher, Comparator)
        for cls_name in ("DictMatcher", "Matcher", "Comparator"):
            cls = getattr(dict_matcher, cls_name, None)
            if cls is not None:
                try:
                    inst = cls()
                    for method_name in ("match", "matches", "compare", "equals"):
                        method = getattr(inst, method_name, None)
                        if callable(method):
                            try:
                                return bool(method(a, b))
                            except Exception:
                                # try next method
                                pass
                except Exception:
                    # try next class name
                    pass

    # Fallback deep equality implementation (mapping order-insensitive)
    def _deep_equal(x, y):
        # Fast identity check
        if x is y:
            return True

        # If both are mappings (dict-like), compare keys and values recursively
        if isinstance(x, Mapping) and isinstance(y, Mapping):
            if set(x.keys()) != set(y.keys()):
                return False
            for k in x.keys():
                if not _deep_equal(x[k], y[k]):
                    return False
            return True

        # Sequences (list/tuple) - compare length and each element in order
        # Exclude str/bytes which are Sequences but should compare directly
        if (isinstance(x, Sequence) and isinstance(y, Sequence)
            and not isinstance(x, (str, bytes)) and not isinstance(y, (str, bytes))):
            if len(x) != len(y):
                return False
            return all(_deep_equal(xi, yi) for xi, yi in zip(x, y))

        # Sets - compare using set equality. Elements must be hashable.
        if isinstance(x, Set) and isinstance(y, Set):
            return x == y

        # Fallback to simple equality for other types
        return x == y

    return _deep_equal(a, b)


# Example usage / quick tests
if __name__ == "__main__":
    a = {"name": "Alice", "age": 30, "meta": {"tags": ["x", "y"]}}
    b = {"age": 30, "meta": {"tags": ["x", "y"]}, "name": "Alice"}
    c = {"name": "Alice", "age": 30, "meta": {"tags": ["y", "x"]}}

    print(dicts_equal(a, b))  # True (different key order)
    print(dicts_equal(a, c))  # False (nested list order differs)
    print(dicts_equal({"a": 1, "b": {"c": 2}}, {"b": {"c": 2}, "a": 1}))  # True
```

