import importlib

def elementwise_strictly_less(lst0: Sequence[Any], lst1: Sequence[Any]) -> List[bool]:
    """
    Given two sequences of equal length, return a list of booleans indicating
    for each index whether lst0[i] < lst1[i].

    This tries to use the external `elementwise_compare` library if available,
    falling back to a simple Python implementation otherwise.

    Raises:
        ValueError: if the two sequences do not have the same length.

    Example:
        elementwise_strictly_less([1, 5, 3], [2, 4, 3]) -> [True, False, False]
    """
    if len(lst0) != len(lst1):
        raise ValueError("Sequences must have equal length")

    # Try to import the library; if unavailable, use Python fallback
    try:
        ec = importlib.import_module("elementwise_compare")
    except ImportError:
        return [a < b for a, b in zip(lst0, lst1)]

    # Common candidate function names in the library
    for fn_name in ("elementwise_lt", "elementwise_less", "lt", "less"):
        if hasattr(ec, fn_name):
            result = getattr(ec, fn_name)(lst0, lst1)
            return list(result)

    # Some libraries provide a generic compare function that accepts an operator
    if hasattr(ec, "compare"):
        cmp = ec.compare
        call_attempts = [
            lambda: cmp(lst0, lst1, "<"),
            lambda: cmp(lst0, lst1, op="<"),
            lambda: cmp(lst0, lst1, operator="<"),
        ]
        for call in call_attempts:
            try:
                result = call()
            except TypeError:
                continue
            else:
                return list(result)

    # Final fallback if library doesn't expose a usable API
    return [a < b for a, b in zip(lst0, lst1)]

Here's a self-contained Python function that returns the indices of elements in a sequence whose values lie inside an inclusive range defined by two bounds. It attempts to use the range_indexer library if it is available (trying a few common APIs), and falls back to a pure-Python linear scan if not. The function is robust to the order of the bounds (low/high swapped) and works with any iterable that supports enumeration (lists, tuples, numpy arrays, etc.).

```python
from typing import Iterable, List, Any

def indices_in_range(seq: Iterable, bound1: Any, bound2: Any) -> List[int]:
    """
    Return the list of indices i for which seq[i] is between bound1 and bound2 inclusive.

    This function will try to use the `range_indexer` library if it is installed and exposes
    a plausible API; if not, it falls back to a simple linear scan.

    Parameters:
    - seq: an iterable sequence (e.g., list, tuple, numpy array) of comparable values
    - bound1, bound2: range bounds (order does not matter)

    Returns:
    - list of integer indices (in ascending order) where seq[i] in [min(bound1,bound2), max(bound1,bound2)]
    """
    low, high = (bound1, bound2) if bound1 <= bound2 else (bound2, bound1)

    # Try to use range_indexer if available (best-effort; tries a few common API names)
    try:
        import range_indexer as ri  # type: ignore
    except Exception:
        ri = None

    if ri is not None:
        # Try a few common factory/class/function names that such a library might provide.
        # This is defensive: if the library isn't exactly one of these shapes, we'll fall back.
        factory_names = [
            'RangeIndexer', 'RangeIndex', 'indexer', 'Indexer', 'IntervalIndexer', 'RangeMap'
        ]
        query_methods = [
            'indices_for_range', 'query', 'between', 'get_indices', 'find', 'lookup', 'locate'
        ]

        for fname in factory_names:
            factory = getattr(ri, fname, None)
            if callable(factory):
                # Try to construct an index object or call factory directly
                try:
                    idx_obj = factory(seq)
                except TypeError:
                    # maybe factory is itself a function that takes (seq, low, high)
                    try:
                        res = factory(seq, low, high)
                        return list(res) if res is not None else []
                    except Exception:
                        idx_obj = None
                except Exception:
                    idx_obj = None

                if idx_obj is not None:
                    # Try a few method names on the index object
                    for mname in query_methods:
                        method = getattr(idx_obj, mname, None)
                        if callable(method):
                            try:
                                res = method(low, high)
                                return list(res) if res is not None else []
                            except TypeError:
                                # maybe requires inclusive flag
                                try:
                                    res = method(low, high, inclusive=True)
                                    return list(res) if res is not None else []
                                except Exception:
                                    pass
                            except Exception:
                                pass
                    # Maybe the index object itself is callable
                    if callable(idx_obj):
                        try:
                            res = idx_obj(low, high)
                            return list(res) if res is not None else []
                        except Exception:
                            pass

        # If we got here, range_indexer was present but none of the attempted APIs worked.
        # Fall through to the safe linear scan.

    # Fallback: simple linear scan (works for all iterables)
    return [i for i, v in enumerate(seq) if v is not None and low <= v <= high]


# Example usage
if __name__ == "__main__":
    data = [0.5, 2.3, -1.0, 4.2, 2.3, 3.0]
    print(indices_in_range(data, 2.3, 3.0))  # -> [1, 4, 5]
    print(indices_in_range(data, 3.5, 1.0))  # bounds reversed -> [1, 4, 5]
