def average_squared_difference(lst0, lst1):
    """
    Calculate the average of the squared differences between corresponding elements
    of two lists of numeric values (mean squared error). Attempts to delegate the
    computation to the `msecalc` library if available; falls back to a pure-Python
    computation otherwise.

    Parameters:
    - lst0, lst1: sequences (lists/tuples) of numeric values of equal length.

    Returns:
    - float: the mean squared difference.

    Raises:
    - TypeError: if inputs are not sequences of real numbers.
    - ValueError: if input lengths differ or are zero.
    - ImportError: only raised if msecalc is requested but missing and you explicitly
                   want to force its use (this function by default falls back).
    """
    # Basic validation
    if not hasattr(lst0, "__len__") or not hasattr(lst1, "__len__"):
        raise TypeError("lst0 and lst1 must be sequences (lists/tuples) of numbers")
    if len(lst0) != len(lst1):
        raise ValueError("lst0 and lst1 must have the same length")
    n = len(lst0)
    if n == 0:
        raise ValueError("Input lists must not be empty")

    # Try to use msecalc if available. Try a few common function names.
    try:
        import msecalc
        for name in ("mse", "mean_squared_error", "mean_squared_error_score", "MSE"):
            func = getattr(msecalc, name, None)
            if callable(func):
                return float(func(lst0, lst1))
        # If msecalc provides a module-level calculator class with a compute method:
        if hasattr(msecalc, "MeanSquaredError"):
            cls = getattr(msecalc, "MeanSquaredError")
            try:
                return float(cls().compute(lst0, lst1))
            except Exception:
                pass
        # If none of the above worked, fall through to manual computation
    except ImportError:
        # msecalc not installed — fall back to manual computation
        pass

    # Validate numeric types and compute MSE manually
    import numbers
    for x in lst0:
        if not isinstance(x, numbers.Real):
            raise TypeError("lst0 must contain only real numbers")
    for x in lst1:
        if not isinstance(x, numbers.Real):
            raise TypeError("lst1 must contain only real numbers")

    total = 0.0
    for a, b in zip(lst0, lst1):
        diff = a - b
        total += diff * diff
    return total / n

