```python
def drop_columns_except(df0, lst0):
    """
    Return a new DataFrame containing all columns from df0 except those named in lst0.

    This function will attempt to use the 'dfcolfilter' library if it is installed.
    If dfcolfilter is not available or a compatible API cannot be found, it falls back
    to using pandas.DataFrame.drop.

    Parameters
    - df0: pandas.DataFrame (or anything convertible to one)
    - lst0: iterable of column names to remove

    Returns
    - pandas.DataFrame with the specified columns removed (non-destructive).
    """
    # Local imports so the function is self-contained
    import pandas as pd

    # Ensure lst0 is a list (or iterable)
    cols_to_remove = list(lst0) if lst0 is not None else []

    # Ensure df0 is a DataFrame (if it isn't, try to make one)
    if not isinstance(df0, pd.DataFrame):
        try:
            df = pd.DataFrame(df0)
        except Exception:
            raise TypeError("df0 must be a pandas DataFrame or convertible to one")
    else:
        # make a shallow copy to avoid modifying caller's object
        df = df0.copy()

    # Try to use dfcolfilter if available and compatible
    try:
        import dfcolfilter as dcf
    except Exception:
        dcf = None

    if dcf is not None:
        # Try a few common API patterns for dfcolfilter
        try:
            # Pattern 1: dcf.filter(df, include=None, exclude=cols)
            if callable(getattr(dcf, "filter", None)):
                try:
                    return dcf.filter(df, include=None, exclude=cols_to_remove)
                except TypeError:
                    # maybe signature is dcf.filter(df, exclude=cols)
                    try:
                        return dcf.filter(df, exclude=cols_to_remove)
                    except Exception:
                        pass

            # Pattern 2: dcf.filter_columns(df, exclude=cols)
            if callable(getattr(dcf, "filter_columns", None)):
                try:
                    return dcf.filter_columns(df, exclude=cols_to_remove)
                except Exception:
                    pass

            # Pattern 3: dcf.select or dcf.select_columns
            if callable(getattr(dcf, "select", None)):
                try:
                    # some libraries accept exclude kw
                    return dcf.select(df, exclude=cols_to_remove)
                except TypeError:
                    # or maybe select takes a selector object; fallthrough
                    pass
            if callable(getattr(dcf, "select_columns", None)):
                try:
                    return dcf.select_columns(df, exclude=cols_to_remove)
                except Exception:
                    pass

            # Pattern 4: ColumnFilter class with exclude parameter
            CF = getattr(dcf, "ColumnFilter", None) or getattr(dcf, "Filter", None)
            if CF is not None:
                try:
                    cf = CF(exclude=cols_to_remove)
                except TypeError:
                    try:
                        # maybe constructor wants include instead; try setting attribute
                        cf = CF()
                        setattr(cf, "exclude", cols_to_remove)
                    except Exception:
                        cf = None
                if cf is not None:
                    # try apply, filter, or call
                    if callable(getattr(cf, "apply", None)):
                        return cf.apply(df)
                    if callable(getattr(cf, "filter", None)):
                        return cf.filter(df)
                    if callable(cf):
                        return cf(df)
        except Exception:
            # If any unexpected error, fall back to pandas below
            pass

    # Fallback: use pandas drop with errors='ignore' so unknown columns are ignored
    return df.drop(columns=cols_to_remove, errors="ignore")
