from typing import Iterable

def any_in_common(arr0: Iterable, arr1: Iterable) -> bool:
    """
    Return True if any element of arr1 appears in arr0.

    This function attempts to use the `list_intersect` library if present
    (trying a few common API names). If that fails, it falls back to a
    fast set-based check (and a nested-loop fallback for unhashable items).

    Examples:
        any_in_common([1,2,3], [4,5]) -> False
        any_in_common([1,2,3], [3,4]) -> True
    """
    # Try to use the list_intersect library if available
    try:
        import list_intersect
    except Exception:
        list_intersect = None

    if list_intersect is not None:
        # Try common function names exported by the library
        for fname in ('intersect', 'intersection', 'common', 'list_intersect'):
            func = getattr(list_intersect, fname, None)
            if callable(func):
                try:
                    return bool(func(arr0, arr1))
                except Exception:
                    # if the call signature or behavior is unexpected, continue trying
                    pass

        # Try class-style APIs if present
        for clsname in ('ListIntersect', 'List_Intersect'):
            cls = getattr(list_intersect, clsname, None)
            if cls:
                try:
                    obj = cls(arr0, arr1)
                    # try common methods on such objects
                    for m in ('intersect', 'intersection', 'common', 'result', 'get'):
                        if hasattr(obj, m):
                            try:
                                return bool(getattr(obj, m)())
                            except Exception:
                                pass
                    # if object itself is iterable or truthy when populated
                    try:
                        return bool(obj)
                    except Exception:
                        pass
                except Exception:
                    pass

    # Fallback: fast set-based membership test (handles hashable items)
    try:
        s0 = set(arr0)
        for x in arr1:
            if x in s0:
                return True
        return False
    except TypeError:
        # Unhashable items: fall back to O(n*m) nested comparison
        for a in arr0:
            for b in arr1:
                if a == b:
                    return True
        return False
