def extract_numerical_comparisons(var0: str) -> List[Dict[str, Any]]:
    """
    Extract each numerical value from the input text together with any associated comparison terms
    or range expressions (e.g., "less than 5", ">= 10", "between 3 and 5", "3-5", "at least 4").
    Uses the `numcomp_extractor` library if available; otherwise falls back to a built-in regex-based extractor.

    Returns a list of dictionaries, each with:
      - text: the exact matched substring
      - operator: normalized operator label (e.g., '<', '<=', '>', '>=', '=', 'between', 'range', 'at_least', 'at_most', 'approx')
      - numbers: list of extracted numbers (ints or floats)
      - span: (start_index, end_index) of match in var0

    Example:
      extract_numerical_comparisons("Patients had between 3 and 5 lesions, more than 2 nodules and <= 10mg.")
      -> [
           {'text': 'between 3 and 5', 'operator': 'between', 'numbers': [3, 5], 'span': (9, 24)},
           {'text': 'more than 2', 'operator': '>', 'numbers': [2], 'span': (26, 37)},
           {'text': '<= 10', 'operator': '<=', 'numbers': [10], 'span': (42, 46)}
         ]
    """
    # Attempt to use numcomp_extractor if available.
    try:
        import numcomp_extractor as nce  # type: ignore
        # Try some reasonable function names that such a library might export.
        if hasattr(nce, "extract"):
            raw = nce.extract(var0)
        elif hasattr(nce, "find_comparisons"):
            raw = nce.find_comparisons(var0)
        elif hasattr(nce, "parse"):
            raw = nce.parse(var0)
        else:
            raw = None

        # If the library returned a usable list-like structure, try to normalize it.
        if isinstance(raw, list):
            out = []
            for item in raw:
                if not isinstance(item, dict):
                    # try common tuple forms: (text, start, end) or (match_text, numbers, operator)
                    if isinstance(item, tuple):
                        # best-effort mapping
                        if len(item) >= 3 and isinstance(item[0], str) and isinstance(item[1], tuple):
                            text = item[0]
                            span = item[1]
                            operator = item[2] if len(item) > 2 else None
                            numbers = []
                        else:
                            text = str(item[0])
                            span = (0, 0)
                            operator = None
                            numbers = []
                    else:
                        text = str(item)
                        span = (0, 0)
                        operator = None
                        numbers = []
                    out.append({"text": text, "operator": operator, "numbers": numbers, "span": span})
                else:
                    # If item is dict, attempt to standardize fields
                    text = item.get("text") or item.get("match") or item.get("span_text") or item.get("raw", "")
                    operator = item.get("operator") or item.get("op") or item.get("label")
                    numbers = item.get("numbers") or item.get("vals") or item.get("values") or []
                    span = item.get("span") or item.get("indices") or (0, 0)
                    # Ensure numbers are numeric types
                    parsed_numbers = []
                    for n in numbers:
                        try:
                            if isinstance(n, str) and re.fullmatch(r"[+-]?\d+(\.\d+)?", n.strip()):
                                num = float(n)
                                if num.is_integer():
                                    num = int(num)
                                parsed_numbers.append(num)
                            elif isinstance(n, (int, float)):
                                parsed_numbers.append(n)
                        except Exception:
                            pass
                    out.append({"text": text, "operator": operator, "numbers": parsed_numbers, "span": span})
            if out:
                return out
        # If library did not return useful output, fall through to regex-based approach.
    except Exception:
        # If import fails or library call fails, we'll use the fallback regex extractor below.
        pass

    # Fallback regex-based extractor
    text = var0 or ""
    results: List[Dict[str, Any]] = []
    seen_spans = set()

    def to_number(s: str):
        s = s.replace(",", "")  # allow numbers with thousand separators
        try:
            if "." in s:
                f = float(s)
                if f.is_integer():
                    return int(f)
                return f
            else:
                return int(s)
        except Exception:
            try:
                return float(s)
            except Exception:
                return s

    # Patterns list: each entry is (regex, operator_label, number_group_indices)
    patterns: List[Tuple[re.Pattern, str, Tuple[int, ...]]] = []

    # "between X and Y" / "between X to Y"
    patterns.append((re.compile(r'\bbetween\s+([+-]?\d+(?:[\.,]\d+)?)\s+(?:and|to)\s+([+-]?\d+(?:[\.,]\d+)?)\b', re.I), 'between', (1, 2)))

    # "from X to Y"
    patterns.append((re.compile(r'\bfrom\s+([+-]?\d+(?:[\.,]\d+)?)\s+(?:to|-)\s+([+-]?\d+(?:[\.,]\d+)?)\b', re.I), 'between', (1, 2)))

    # Hyphenated ranges like "3-5" or "3 - 5" (ensure word boundaries and not catch dates like 2020-01-01 too aggressively)
    patterns.append((re.compile(r'(?<!\d)([+-]?\d+(?:[\.,]\d+)?)\s*-\s*([+-]?\d+(?:[\.,]\d+)?)(?!\d)', re.I), 'range', (1, 2)))

    # Comparison words before number
    comp_words_before = [
        ('<=|less than or equal to|less than or equal|no more than|at most', '<='),
        ('<|less than|under|below', '<'),
        ('>=|greater than or equal to|greater than or equal|no less than|at least', '>='),
        ('>|greater than|more than|over|above', '>'),
        ('=|equals|equal to|equal', '='),
    ]
    for words, op in comp_words_before:
        # Use word boundaries and allow optional punctuation between phrase and number
        pattern = re.compile(r'\b(?:' + words + r')\b[\s:;-]*([+-]?\d+(?:[\.,]\d+)?)(?!\w)', re.I)
        patterns.append((pattern, op, (1,)))

    # Phrases where number comes before phrase e.g., "5 or more", "5 or less"
    patterns.append((re.compile(r'([+-]?\d+(?:[\.,]\d+)?)\s+(?:or\s+more|and\s+up|or\s+higher|or\s+above)\b', re.I), '>=', (1,)))
    patterns.append((re.compile(r'([+-]?\d+(?:[\.,]\d+)?)\s+(?:or\s+less|and\s+down|or\s+lower|or\s+below)\b', re.I), '<=', (1,)))
    patterns.append((re.compile(r'([+-]?\d+(?:[\.,]\d+)?)\s+(?:or more|or less)\b', re.I), None, (1,)))  # ambiguous; we'll leave operator None

    # Comparison symbols like "<=10", "> 5", "= 4"
    patterns.append((re.compile(r'([<>]=?|=)\s*([+-]?\d+(?:[\.,]\d+)?)', re.I), None, (1, 2)))
    # Number followed by symbol (rare) e.g., "5 <"
    patterns.append((re.compile(r'([+-]?\d+(?:[\.,]\d+)?)\s*(<=|>=|<|>|=)\b', re.I), None, (1, 2)))

    # Iterate patterns and collect matches
    for pattern, op_label, groups in patterns:
        for m in pattern.finditer(text):
            start, end = m.span()
            if (start, end) in seen_spans:
                continue
            seen_spans.add((start, end))
            raw_match = m.group(0)
            nums = []
            # extract numbers from specified groups; some patterns put operator symbol in group 1
            for gi in groups:
                try:
                    g = m.group(gi)
                except IndexError:
                    g = None
                if g is None:
                    continue
                # if group looks like an operator symbol (<, <=, etc.), skip numeric conversion for that group
                if re.fullmatch(r'[<>]=?|=', g.strip()):
                    continue
                # normalize decimal commas to dots
                g_norm = g.replace(",", ".")
                if re.fullmatch(r'[+-]?\d+(?:\.\d+)?', g_norm.strip()):
                    nums.append(to_number(g_norm.strip()))
                else:
                    # fallback: find any number inside the group
                    inner = re.search(r'[+-]?\d+(?:[\.,]\d+)?', g)
                    if inner:
                        nums.append(to_number(inner.group(0).replace(",", ".")))
            # Determine normalized operator
            operator = None
            if op_label is not None:
                operator = op_label
            else:
                # infer from matched text for symbol patterns
                sym = None
                # check for symbol in match
                sym_m = re.search(r'([<>]=?|=)', raw_match)
                if sym_m:
                    sym = sym_m.group(1)
                # check for words
                lw = raw_match.lower()
                if sym:
                    operator = sym
                elif 'between' in lw or 'from' in lw:
                    operator = 'between'
                elif 'or more' in lw or 'or higher' in lw or 'or above' in lw or 'or more' in lw or 'and up' in lw:
                    operator = '>='
                elif 'or less' in lw or 'or lower' in lw or 'or below' in lw or 'and down' in lw:
                    operator = '<='
                elif 'more than' in lw or 'greater than' in lw or 'over' in lw or 'above' in lw:
                    operator = '>'
                elif 'less than' in lw or 'under' in lw or 'below' in lw:
                    operator = '<'
                elif 'at least' in lw or 'no less' in lw:
                    operator = '>='
                elif 'at most' in lw or 'no more' in lw:
                    operator = '<='
                elif 'between' in lw:
                    operator = 'between'
                else:
                    operator = None

            # For 'range' or 'between' patterns we expect two numbers; for single-number comparisons expect one
            # If hyphen range was matched but numbers are reversed, keep as-is
            entry = {
                "text": raw_match,
                "operator": operator,
                "numbers": nums,
                "span": (start, end)
            }
            results.append(entry)

    # Deduplicate overlapping matches by favoring longer spans (to avoid returning both "3 - 5" and "3")
    # Sort by start then -length
    results_sorted = sorted(results, key=lambda e: (e["span"][0], -(e["span"][1]-e["span"][0])))
    final: List[Dict[str, Any]] = []
    occupied = [False] * (len(text) + 1)
    for item in results_sorted:
        s, e = item["span"]
        # if any character in span already occupied by a previously selected (longer) match, skip
        if any(occupied[i] for i in range(s, max(s+1, e))):
            continue
        for i in range(s, max(s+1, e)):
            occupied[i] = True
        final.append(item)

    # Sort final results by their position in text
    final = sorted(final, key=lambda x: x["span"][0])
    return final
