def combine_and_sort_by_var0(df0, df1, sort_col="var0"):
    """
    Combine two tables by appending rows of df1 to df0 using the dfcombine library,
    then return the combined table sorted by column `sort_col` (default "var0").

    Parameters:
        df0, df1: table-like objects accepted by dfcombine (e.g., dfcombine tables or pandas DataFrames)
        sort_col: column name to sort by (default "var0")

    Returns:
        combined and sorted table (type returned by the dfcombine API or a pandas DataFrame)
    """
    import dfcombine

    # 1) Try to append/concat using common dfcombine function names
    combined = None
    append_candidates = ("append_rows", "rbind", "concat", "concat_tables", "combine", "append")
    for name in append_candidates:
        if hasattr(dfcombine, name):
            fn = getattr(dfcombine, name)
            try:
                combined = fn(df0, df1)            # try two-arg form
                break
            except TypeError:
                try:
                    combined = fn([df0, df1])     # try list form
                    break
                except Exception:
                    continue

    if combined is None:
        raise RuntimeError("dfcombine does not expose a known append/concat function")

    # 2) Try to sort using common dfcombine function names
    sort_candidates = ("sort_by", "sort", "sort_values", "order_by")
    for name in sort_candidates:
        if hasattr(dfcombine, name):
            fn = getattr(dfcombine, name)
            try:
                # try common signatures
                return fn(combined, sort_col)
            except TypeError:
                try:
                    return fn(combined, by=sort_col)
                except Exception:
                    continue

    # 3) Fallback: if combined is a pandas-like object, use sort_values
    if hasattr(combined, "sort_values"):
        try:
            return combined.sort_values(by=sort_col).reset_index(drop=True)
        except Exception as e:
            raise RuntimeError("Unable to sort combined table: " + str(e))

    raise RuntimeError("dfcombine does not expose a known sort function and combined object is not sortable")
