def upcase_column(table, column):
    """
    Transform all entries in a specified column of a 2D data table to uppercase,
    using the `data_upcase` library when available.

    The function accepts:
    - table: one of
        - pandas.DataFrame
        - list of dicts (each dict is a row)
        - list of lists (optionally with a header row)
    - column: either an integer index (0-based) or a string column name/key

    Returns a modified copy of the input table (does not mutate the original).

    Behavior notes:
    - If the `data_upcase` module exposes a callable helper (checked by name:
      'upcase', 'upcase_value', 'uppercase', 'to_upper', 'upper'), the function
      will try to use that for conversion. If not available or it fails, it
      falls back to str(value).upper().
    - None values are preserved as None.
    - If column is an integer and the table is a list of dicts, the integer is
      treated as the index into the first row's keys() ordering (insertion order
      for Python 3.7+). For list-of-lists, an integer is the column index.
    - Raises ValueError or TypeError for unsupported inputs or missing columns.
    """
    import copy

    # Try to import data_upcase; if not available, we'll use fallback behavior.
    try:
        import data_upcase as du
    except Exception:
        du = None

    # helper that attempts to use data_upcase API if present, else fallback
    def _upcase_val(v):
        if v is None:
            return None
        # try known names in the data_upcase module
        if du is not None:
            for name in ("upcase", "upcase_value", "uppercase", "to_upper", "upper"):
                func = getattr(du, name, None)
                if callable(func):
                    try:
                        return func(v)
                    except Exception:
                        # if the data_upcase function fails for this value, try next
                        continue
        # fallback
        try:
            return str(v).upper()
        except Exception:
            return v

    # Handle pandas DataFrame if pandas is available
    try:
        import pandas as pd
    except Exception:
        pd = None

    # 1) pandas DataFrame
    if pd is not None and isinstance(table, pd.DataFrame):
        df = table.copy(deep=True)
        # resolve column name from index if needed
        if isinstance(column, int):
            try:
                col_name = df.columns[column]
            except Exception:
                raise ValueError(f"Column index {column} out of range for DataFrame with columns {list(df.columns)}")
        else:
            col_name = column
            if col_name not in df.columns:
                raise ValueError(f"Column name {col_name!r} not found in DataFrame columns {list(df.columns)}")
        # Apply conversion elementwise
        df[col_name] = df[col_name].apply(_upcase_val)
        return df

    # 2) list of dicts
    if isinstance(table, list) and table and all(isinstance(r, dict) for r in table):
        rows = []
        # determine key if column given as int
        if isinstance(column, int):
            # get keys order from first row
            first_keys = list(table[0].keys())
            try:
                key = first_keys[column]
            except Exception:
                raise ValueError(f"Column index {column} out of range for dict keys {first_keys}")
        else:
            key = column
        for row in table:
            new_row = row.copy()
            if key in new_row:
                new_row[key] = _upcase_val(new_row.get(key))
            else:
                # if key missing, keep row as-is; you could also raise depending on desired behavior
                pass
            rows.append(new_row)
        return rows

    # 3) list of lists (optionally with header)
    if isinstance(table, list) and table and all(isinstance(r, list) for r in table):
        # copy all rows (shallow copy of inner lists)
        rows = [list(r) for r in table]
        # if column is a string, treat first row as header and find index
        if isinstance(column, str):
            header = rows[0]
            if column not in header:
                raise ValueError(f"Header {column!r} not found in first row header {header}")
            col_idx = header.index(column)
            # transform values in subsequent rows (rows[1:])
            for i in range(1, len(rows)):
                # only modify if index exists in this row
                if col_idx < len(rows[i]):
                    rows[i][col_idx] = _upcase_val(rows[i][col_idx])
        else:
            # column expected to be integer index
            if not isinstance(column, int):
                raise TypeError("For list-of-lists tables, column must be str (header) or int (index).")
            col_idx = column
            for i in range(len(rows)):
                if col_idx < len(rows[i]):
                    rows[i][col_idx] = _upcase_val(rows[i][col_idx])
        return rows

    # 4) empty list: nothing to do
    if isinstance(table, list) and not table:
        return []

    raise TypeError("Unsupported table format. Expected pandas.DataFrame, list of dicts, or list of lists.")
