Below is a self-contained Python function that filters rows from a two-dimensional table according to multiple conditions. It will work whether your table is a list of lists (optionally with headers), a list of dicts, or a list of namedtuples. The function attempts to use the tablefilter library if it is installed; if not, it falls back to a pure-Python implementation (so it will always work).

Supported condition operators:
- Comparison: '==', '!=', '<', '<=', '>', '>='
- Membership/substring: 'in', 'contains'
- String prefix/suffix: 'startswith', 'endswith'
- Regular expression: 'regex'

You can combine conditions with mode='and' (default) or mode='or'.

Usage example:
- For a list-of-lists table with headers:
  conditions = [{'column': 'age', 'op': '>=', 'value': 21}, {'column': 'country', 'op': 'in', 'value': ['US','CA']}]
- For a list-of-dicts table:
  conditions = [{'column': 'status', 'op': '==', 'value': 'active'}]

Function code:

```python
from typing import Any, List, Dict, Union, Sequence, Optional
import re

def filter_table_rows(
    table: Sequence[Sequence[Any]],
    conditions: List[Dict[str, Any]],
    headers: Optional[Sequence[str]] = None,
    mode: str = 'and'
) -> List[Sequence[Any]]:
    """
    Filter rows of a 2D table according to multiple conditions.

    Parameters:
    - table: list of rows. Each row can be:
        * a sequence (list/tuple) of values (if so, provide headers or use column indices),
        * a dict (mapping column names to values),
        * a namedtuple (works like a tuple but headers may be used).
    - conditions: list of condition dicts. Each condition dict must contain:
        * 'column' : int (index) or str (header/key),
        * 'op'     : operator as string: '==','!=','<','<=','>','>=','in','contains','startswith','endswith','regex'
        * 'value'  : value to compare against (for 'in', can be list or string; for 'regex' supply a pattern)
    - headers: optional sequence of header names for list-of-lists input (maps names to indices).
    - mode: 'and' (all conditions must match) or 'or' (any condition matches).

    Returns:
    - List of rows (same format as input rows) that match the conditions.
    """
    # Try to use tablefilter library when available (best-effort);
    # If unavailable or if it doesn't provide a suitable API, fall back to pure-Python implementation.
    try:
        import tablefilter as tf  # type: ignore
    except Exception:
        tf = None

    # Helper to get column value from a row given column spec (index or name)
    def get_value(row, col):
        if isinstance(col, int):
            # index
            try:
                return row[col]
            except Exception:
                return None
        # name
        if isinstance(row, dict):
            return row.get(col, None)
        # sequence (list/tuple) with headers mapping
        if headers is not None:
            try:
                idx = headers.index(col)
                return row[idx]
            except ValueError:
                return None
        # namedtuple or attribute access?
        if hasattr(row, col):
            try:
                return getattr(row, col)
            except Exception:
                return None
        return None

    # Helper to try to coerce strings that look numeric to floats for numeric comparisons
    def _try_number(x):
        if isinstance(x, (int, float)):
            return x
        if isinstance(x, str):
            try:
                if x.strip() == '':
                    return x
                return float(x)
            except Exception:
                return x
        return x

    # Evaluate single condition for a row
    def eval_condition(row, cond):
        col = cond['column']
        op = cond['op']
        val = cond.get('value', None)
        v = get_value(row, col)

        # For numeric comparisons, attempt numeric coercion if both look numeric
        if op in ('<', '<=', '>', '>='):
            a = _try_number(v)
            b = _try_number(val)
            try:
                if a is None or b is None:
                    return False
                return {
                    '<': lambda: a < b,
                    '<=': lambda: a <= b,
                    '>': lambda: a > b,
                    '>=': lambda: a >= b,
                }[op]()
            except Exception:
                return False

        if op == '==':
            return v == val
        if op == '!=':
            return v != val

        if op == 'in':
            # membership: if val is sequence -> v in val
            # if v is sequence/string -> val in v
            if val is None:
                return False
            try:
                if isinstance(val, (list, tuple, set)):
                    return v in val
                # if val is string and v is string, check substring
                if isinstance(val, str) and isinstance(v, str):
                    return val in v
                # otherwise check membership the other way
                if hasattr(v, '__contains__'):
                    return val in v
            except Exception:
                return False
            return False

        if op == 'contains':
            # check if v (string or container) contains val
            if v is None or val is None:
                return False
            try:
                if isinstance(v, str):
                    return str(val) in v
                if hasattr(v, '__contains__'):
                    return val in v
            except Exception:
                return False
            return False

        if op == 'startswith':
            try:
                return isinstance(v, str) and v.startswith(str(val))
            except Exception:
                return False

        if op == 'endswith':
            try:
                return isinstance(v, str) and v.endswith(str(val))
            except Exception:
                return False

        if op == 'regex':
            try:
                if v is None:
                    return False
                return re.search(val, str(v)) is not None
            except Exception:
                return False

        # Unknown operator
        raise ValueError(f"Unsupported operator: {op}")

    # If tablefilter is available and defines a convenient API, you could plug it here.
    # We do not assume a specific stable API across versions; use fallback implementation.
    # Fallback pure-Python:
    mode = mode.lower()
    if mode not in ('and', 'or'):
        raise ValueError("mode must be 'and' or 'or'")

    out_rows = []
    for row in table:
        results = [bool(eval_condition(row, c)) for c in conditions]
        match = all(results) if mode == 'and' else any(results)
        if match:
            out_rows.append(row)

    return out_rows
