Here's a self-contained Python function that reorders a mapping from keys to sequences so entries are sorted by the highest number in each sequence (descending by default). It will use the external sort_dict_by_max library if available; if not, it falls back to an internal implementation. Empty sequences are treated as having a very small max so they appear last when descending=True.

```python
from typing import Mapping, MutableMapping, Sequence, Any, Dict

def reorder_by_max(mapping: Mapping[Any, Sequence[float]], descending: bool = True) -> Dict[Any, Sequence[float]]:
    """
    Return a new dict with entries ordered by the maximum value in each associated sequence.
    By default sorts in descending order (largest max first).

    Behavior:
    - Uses the external `sort_dict_by_max` library if importable.
      The function attempts several common call signatures and return formats from that library.
    - If the library is not available, falls back to a local implementation.
    - Empty sequences are treated as having max = -inf (so they end up last when descending=True).
    - If sequence elements are not comparable (non-numeric or mixed types), a ValueError is raised.

    Args:
        mapping: Mapping from keys to sequences of numbers.
        descending: If True (default), sort largest-first; otherwise smallest-first.

    Returns:
        A new dict whose items are ordered according to the max value in each sequence.

    Example:
        data = {"a": [1, 2], "b": [10], "c": []}
        reorder_by_max(data)  # -> {"b": [10], "a": [1, 2], "c": []}
    """
    # Try to use the sort_dict_by_max library if available.
    sort_func = None
    try:
        # common pattern: library exposes sort_dict_by_max
        from sort_dict_by_max import sort_dict_by_max as sort_func  # type: ignore
    except Exception:
        sort_func = None

    if sort_func is not None:
        # Try a few possible call signatures and return formats to be robust.
        try:
            # try typical signature: sort_func(mapping, reverse=...)
            result = sort_func(mapping, reverse=descending)
            if isinstance(result, dict):
                return result
            if isinstance(result, list):
                return dict(result)
            # if it's an iterable of pairs
            return dict(result)
        except TypeError:
            try:
                # alternate signature: sort_func(mapping, descending=...)
                result = sort_func(mapping, descending=descending)
                if isinstance(result, dict):
                    return result
                return dict(result)
            except Exception:
                # Fall back to local implementation below if the library call fails
                pass
        except Exception:
            # Fall back on any other exception from the library call
            pass

    # Local fallback implementation
    def safe_max(seq):
        try:
            return max(seq)
        except ValueError:
            # empty sequence -> treat as -inf for descending (so goes last)
            return float("-inf") if descending else float("inf")
        except TypeError as exc:
            raise ValueError("Sequence elements must be comparable (numeric).") from exc

    items = sorted(mapping.items(), key=lambda kv: safe_max(kv[1]), reverse=descending)
    return dict(items)
