def add_two_pairs(dict0, var0, var1, var2, var3):
    """
    Return a dict like dict0 but with two additional key/value pairs:
      - key var0 -> value var1
      - key var2 -> value var3

    This function will attempt to use the `dictaugment` library if available.
    If `dictaugment` is not installed or does not expose a suitable API,
    the function falls back to the standard dict.update behaviour.

    The original dict0 is not mutated; a shallow copy is returned.
    """
    # Make a shallow copy so we don't mutate the caller's dict
    if isinstance(dict0, dict):
        out = dict0.copy()
    else:
        out = dict(dict0)

    # convenience mapping of the two pairs
    additions = {var0: var1, var2: var3}

    def _use_result_or_keep(orig, result):
        # Some dictaugment functions may modify in-place and return None,
        # while others may return a new dict. Normalize to a dict return.
        return orig if result is None else result

    try:
        import dictaugment as da
        # Try a few common names that such a library might expose.
        if hasattr(da, "augment"):
            out = _use_result_or_keep(out, da.augment(out, additions))
        elif hasattr(da, "update"):
            # da.update might behave like dict.update or return a new dict
            out = _use_result_or_keep(out, da.update(out, additions))
        elif hasattr(da, "add"):
            # add could accept (dict, key, value) or (dict, mapping)
            fn = da.add
            try:
                out = _use_result_or_keep(out, fn(out, additions))
            except TypeError:
                out = _use_result_or_keep(out, fn(out, var0, var1))
                out = _use_result_or_keep(out, fn(out, var2, var3))
        elif hasattr(da, "set"):
            out = _use_result_or_keep(out, da.set(out, var0, var1))
            out = _use_result_or_keep(out, da.set(out, var2, var3))
        elif hasattr(da, "insert"):
            out = _use_result_or_keep(out, da.insert(out, var0, var1))
            out = _use_result_or_keep(out, da.insert(out, var2, var3))
        else:
            # No known API found on dictaugment: fall back to builtin update
            out.update(additions)
    except Exception:
        # dictaugment not present or something went wrong: fallback
        out.update(additions)

    return out

