    Fetch all entries from a key-value collection whose keys fall between two boundary keys.

    Parameters
    - collection: either a kv_range collection object or the name/identifier of a collection
      (if a string is provided, the function will try to open it via kv_range.open_collection).
    - start_key: lower boundary key (inclusive/exclusive controlled by include_start). If None, no lower bound.
    - end_key: upper boundary key (inclusive/exclusive controlled by include_end). If None, no upper bound.
    - include_start: whether to include entries whose key == start_key.
    - include_end: whether to include entries whose key == end_key.
    - limit: optional maximum number of entries to return. If None, fetch all matching entries.

    Returns
    - List of (key, value) tuples for entries with keys in the requested range (respecting ordering
      provided by the underlying collection/iterator). If the underlying API provides streaming
      results, this function will consume them into a list (up to `limit` if provided).

    Notes
    - This function attempts to be robust to a variety of plausible kv_range APIs:
      * collection.range(...) or collection.scan(...)
      * kv_range.scan_range(collection, ...) or kv_range.range(...)
      * fallback: iterate the collection and filter keys in Python
    - It also normalizes returned items that may be tuples, dicts like {'key': ..., 'value': ...},
      or objects with .key and .value attributes.
    """

    # Helper: open collection if user passed a string name
    if isinstance(collection, str):
        # try common open function names
        if hasattr(kv_range, "open_collection"):
            collection = kv_range.open_collection(collection)
        elif hasattr(kv_range, "collection"):
            collection = kv_range.collection(collection)
        else:
            raise ValueError("kv_range does not expose an obvious open_collection API; "
                             "pass a collection object instead of a string name")

    # Helper: normalize one returned item into (key, value)
    def _normalize_item(item: Any) -> Entry:
        if isinstance(item, tuple) and len(item) == 2:
            return item  # (key, value)
        if isinstance(item, dict):
            if "key" in item and "value" in item:
                return (item["key"], item["value"])
            # maybe single-entry dict {key: value}
            if len(item) == 1:
                k = next(iter(item))
                return (k, item[k])
        # object-like
        if hasattr(item, "key") and hasattr(item, "value"):
            return (getattr(item, "key"), getattr(item, "value"))
        # last resort: maybe item is (key, value, ...) or [key, value]
        try:
            seq = list(item)
            if len(seq) >= 2:
                return (seq[0], seq[1])
        except Exception:
            pass
