                        return False
                else:
                    if k == start_key:
                        return False
            if end_key is not None:
                if include_end:
                    if k != end_key and end_key != None:
                        return False
                else:
                    if k == end_key:
                        return False
            # If we reach here, only equality checks passed; assume in range
