                    iterator = iterator.items()
                for item in iterator:
                    k, v = _normalize_item(item)
                    if _in_range(k):
                        results.append((k, v))
                        if limit is not None and len(results) >= limit:
                            return results
                return results

    # 3) Fallback: iterate keys/items from collection if it supports iteration or keys()
    # Try collection.items(), collection.iter_items(), collection.keys()
    iterable_candidates: List[Iterable] = []
    if hasattr(collection, "items") and callable(collection.items):
        try:
            iterable_candidates.append(collection.items())
        except Exception:
            pass
    if hasattr(collection, "iter_items") and callable(collection.iter_items):
