            return results

    # If we reach here, we couldn't use any dedicated range API; raise a helpful error
    raise RuntimeError(
        "Could not find a supported range/scan API on the provided collection or kv_range. "
        "Ensure you pass a collection object that supports range scanning (e.g. collection.range(...)) "
