def count_whole_word_occurrences(text, word, case_sensitive=False):
    """
    Count occurrences of `word` as a whole word in `text`.

    This function prefers to use the `wordmatcher` library if it is available
    (trying several plausible APIs), and falls back to `re` if not.
    Word boundaries are enforced using pattern-based matching: the pattern used
    is r'\b<escaped_word>\b'.

    Parameters:
    - text (str): the text to search.
    - word (str): the target word to count (treated as a whole word).
    - case_sensitive (bool): if False (default), matching is case-insensitive.

    Returns:
    - int: total number of whole-word occurrences of `word` in `text`.

    Example:
    >>> count_whole_word_occurrences("Hello world. Hello-world hello", "hello")
    2
    """
    import re

    # Build a regex pattern enforcing whole-word boundaries and escape the word.
    pattern_str = r'\b' + re.escape(word) + r'\b'
    flags = 0 if case_sensitive else re.IGNORECASE

    # Try to use wordmatcher if available. Try a few plausible APIs.
    try:
        import wordmatcher
    except Exception:
        wordmatcher = None

    if wordmatcher is not None:
        # 1) Try wordmatcher.compile(...) returning a pattern object with finditer
        try:
            if hasattr(wordmatcher, 'compile'):
                # Some hypothetical APIs accept flags as second arg; try both ways.
                try:
                    compiled = wordmatcher.compile(pattern_str, flags)
                except TypeError:
                    compiled = wordmatcher.compile(pattern_str)
                # If compiled has finditer or find_all, use it
                if hasattr(compiled, 'finditer'):
                    return sum(1 for _ in compiled.finditer(text))
                if hasattr(compiled, 'find_all'):
                    return len(compiled.find_all(text))
                # If compiled is directly iterable of matches
                try:
                    return sum(1 for _ in compiled)
                except Exception:
                    pass
        except Exception:
            pass

        # 2) Try a Pattern class API
        try:
            Pattern = getattr(wordmatcher, 'Pattern', None)
            if Pattern is not None:
                try:
                    pat = Pattern(pattern_str, flags=flags)
                except TypeError:
                    pat = Pattern(pattern_str)
                if hasattr(pat, 'finditer'):
                    return sum(1 for _ in pat.finditer(text))
                if hasattr(pat, 'find_all'):
                    return len(pat.find_all(text))
        except Exception:
            pass

        # 3) Try a Matcher class API
        try:
            Matcher = getattr(wordmatcher, 'Matcher', None)
            if Matcher is not None:
                try:
                    matcher = Matcher(pattern_str, flags=flags)
                except TypeError:
                    matcher = Matcher(pattern_str)
                if hasattr(matcher, 'finditer'):
                    return sum(1 for _ in matcher.finditer(text))
                if hasattr(matcher, 'find_all'):
                    return len(matcher.find_all(text))
                if hasattr(matcher, 'count'):
                    return int(matcher.count(text))
        except Exception:
            pass

        # 4) Try module-level finditer/findall functions
        try:
            if hasattr(wordmatcher, 'finditer'):
                return sum(1 for _ in wordmatcher.finditer(pattern_str, text, flags=flags))
            if hasattr(wordmatcher, 'findall'):
                return len(wordmatcher.findall(pattern_str, text, flags=flags))
        except Exception:
            pass

    # Final fallback: use Python's re module
    return len(re.findall(pattern_str, text, flags=flags))
