        import dictfactory
    except Exception:
        return _fallback()

    # Try a few common API patterns on the dictfactory module.
    # If any call returns a Mapping, we accept it.
    candidates = (
        "fromkeys",
        "dict_fromkeys",
        "dict_factory",
        "make",
