                except Exception:
                    continue
            try:
                for k in var0:
                    container[k] = var1
                if isinstance(container, Mapping):
                    return container
            except Exception:
                continue
        except Exception:
            continue

    # As a last attempt, try calling the module (some factories are callable)
    try:
