from collections.abc import MutableMapping

def _require_not_none(obj, name='value'):
    """
    Try to use the noneguard library to assert obj is not None.
    If noneguard isn't available or doesn't provide a compatible call,
    fall back to a simple runtime check that raises ValueError for None.
    """
    try:
        import noneguard as ng
        # Attempt a few common exported function names and calling styles.
        for fname in ('not_none', 'assert_not_none', 'require_non_none',
                      'require_not_none', 'check_not_none', 'check'):
            if hasattr(ng, fname):
                fn = getattr(ng, fname)
                try:
                    # Some functions accept just the object, some accept (obj, name).
                    try:
                        fn(obj)
                    except TypeError:
                        fn(obj, name)
                    return
                except Exception:
                    # If noneguard call raises, ignore and fall back
                    pass
    except Exception:
        # noneguard not installed or import failed: fall back below
        pass

    if obj is None:
        raise ValueError(f"'{name}' must not be None")


def set_value_if_none(dict0, var0, value):
    """
    Set dict0[var0] = value only if the current entry for var0 is None.
    Returns True if the assignment was performed, False otherwise.

    Behavior:
    - If dict0.get(var0) is None (including when the key is missing), the function sets dict0[var0] = value and returns True.
    - If dict0.get(var0) is not None, the function leaves the mapping unchanged and returns False.

    This function uses the noneguard library (if available) to assert inputs are not None;
    otherwise it falls back to a standard runtime check.
    """
    _require_not_none(dict0, 'dict0')

    if not isinstance(dict0, MutableMapping):
        raise TypeError("dict0 must be an associative container (MutableMapping), e.g. a dict")

    current = dict0.get(var0, None)
    if current is None:
        dict0[var0] = value
        return True
    return False
