def generate_cartesian(lst0):
    """
    Return the Cartesian product of the sequence of sequences `lst0`.
    Uses the cartesianpy library if available (tries several common function names),
    otherwise falls back to itertools.product.

    The result is returned as a list of tuples, one tuple per combination.

    Example:
        >>> generate_cartesian([[1,2], ['a','b']])
        [(1, 'a'), (1, 'b'), (2, 'a'), (2, 'b')]
    """
    # Basic validation
    if lst0 is None:
        raise TypeError("lst0 must be an iterable of iterables, got None")

    try:
        import cartesianpy
    except Exception:
        cartesianpy = None

    raw = None

    if cartesianpy is not None:
        # Try a few likely function names and call forms that cartesianpy might provide
        func_names = ('cartesian', 'product', 'cartesian_product')
        for name in func_names:
            func = getattr(cartesianpy, name, None)
            if callable(func):
                try:
                    raw = func(*lst0)        # try unpacked args
                except TypeError:
                    try:
                        raw = func(lst0)    # try single-arg form
                    except TypeError:
                        raw = None
                break

    if raw is None:
        # Fallback to itertools.product
        from itertools import product
        raw = product(*lst0)

    # Ensure we return a collection of tuples
    return [tuple(item) for item in raw]
