def sort_table_with_sortframe(data0, cols0, ascending=True):
    """
    Sort a tabular dataset `data0` by the columns in `cols0` using the sortframe library.

    The function attempts these strategies (in order):
    1. Call common sortframe top-level functions (e.g. sort, sort_frame, sort_by).
    2. Call sorting methods on data0 (e.g. sort, sort_values).
    3. Fall back to pandas.DataFrame.sort_values (also converting to/from pandas if needed).

    Parameters
    - data0: tabular dataset (expected to be a sortframe object or a pandas.DataFrame or similar)
    - cols0: list/tuple of column names (strings) to sort by, in priority order
    - ascending: bool or list of bools indicating sort direction (default True)

    Returns
    - The sorted dataset (type depends on input and available conversion functions).

    Raises
    - TypeError if cols0 is not a list/tuple of strings.
    - ValueError if a requested column does not appear to exist in data0 (best-effort check).
    - RuntimeError if no supported sorting API is found.
    """
    # Validate cols0
    if not isinstance(cols0, (list, tuple)):
        raise TypeError("cols0 must be a list or tuple of column names (strings).")
    if not all(isinstance(c, str) for c in cols0):
        raise TypeError("All items in cols0 must be strings (column names).")

    # Import sortframe (required by the user's request)
    try:
        import sortframe
    except Exception as e:
        raise RuntimeError("Could not import sortframe library: {}".format(e))

    # Helper: best-effort check if data0 appears to contain the columns
    def has_columns(obj, cols):
        # check common attributes (.columns, schema, column_names, keys)
        try:
            cols_attr = getattr(obj, "columns", None)
            if cols_attr is not None:
                # pandas Index or list-like
                return all(c in cols_attr for c in cols)
        except Exception:
            pass
        try:
            schema = getattr(obj, "schema", None)
            if schema is not None:
                # schema might be dict-like or list
                if isinstance(schema, dict):
                    keys = list(schema.keys())
                else:
                    keys = list(schema)
                return all(c in keys for c in cols)
        except Exception:
            pass
        try:
            names = getattr(obj, "column_names", None)
            if names is not None:
                return all(c in names for c in cols)
        except Exception:
            pass
        # last resort: if obj has to_pandas, try converting
        try:
            if hasattr(obj, "to_pandas"):
                df = obj.to_pandas()
                return all(c in df.columns for c in cols)
        except Exception:
            pass
        return False

    # If we can detect missing columns upfront, raise informative error
    if not has_columns(data0, cols0):
        # give user a warning-like error: maybe conversion required; try to continue but also inform
        # We'll not immediately error because sortframe/pandas conversion might still succeed.
        pass

    # Try common top-level APIs in sortframe
    sortframe_api_candidates = [
        "sort",
        "sort_frame",
        "sortframe",
        "sort_by",
        "sort_values",
        "sorted_frame",
    ]
    for name in sortframe_api_candidates:
        if hasattr(sortframe, name):
            func = getattr(sortframe, name)
            try:
                # try calling with ascending keyword first
                return func(data0, cols0, ascending=ascending)
            except TypeError:
                # maybe signature is (data, cols) only
                try:
                    return func(data0, cols0)
                except Exception:
                    pass
            except Exception:
                # other runtime errors: try next candidate
                pass

    # Try methods on the object itself
    # Common method names: sort, sort_values, sort_by
    method_candidates = [
        ("sort", ("cols", "by", "keys")),
        ("sort_values", ("by",)),
        ("sort_by", ("keys", "by")),
    ]
    for method_name, _ in method_candidates:
        if hasattr(data0, method_name):
            method = getattr(data0, method_name)
            try:
                # Try typical pandas-like signature first
                return method(by=cols0, ascending=ascending)
            except TypeError:
                # Try positional
                try:
                    return method(cols0, ascending)
                except TypeError:
                    try:
                        return method(cols0)
                    except Exception:
                        pass
            except Exception:
                pass

    # Try converting to pandas and using pandas sort_values
    try:
        import pandas as pd
        if isinstance(data0, pd.DataFrame):
            return data0.sort_values(by=list(cols0), ascending=ascending).reset_index(drop=True)
        # If data0 can be converted to pandas
        if hasattr(data0, "to_pandas"):
            try:
                df = data0.to_pandas()
                df_sorted = df.sort_values(by=list(cols0), ascending=ascending).reset_index(drop=True)
                # If sortframe exposes from_pandas, convert back
                if hasattr(sortframe, "from_pandas"):
                    try:
                        return sortframe.from_pandas(df_sorted)
                    except Exception:
                        return df_sorted
                return df_sorted
            except Exception:
                pass
    except Exception:
        # pandas not available or conversion failed; continue
        pass

    # If we reach here, we couldn't find a supported API
    raise RuntimeError(
        "Unable to sort with the available sortframe APIs or object methods. "
        "Ensure `sortframe` provides a sorting function (e.g. sort, sort_frame, sort_by) "
        "or that data0 is a pandas.DataFrame (or supports to_pandas())."
    )
