def sum_duplicate_headers(table):
    """
    Sum the values of columns that share the same header, returning a DataFrame
    with each header appearing only once.

    - Uses the `colmerge` library if available (attempts a sensible call).
    - If `colmerge` is not installed or its API is not recognized, falls back to
      a pandas-based implementation.
    - Accepts:
        - a pandas.DataFrame
        - a list of dicts (records)
        - a list-of-lists where the first row is the header
    - Returns: pandas.DataFrame with unique column names and summed values
      (numeric columns are summed; non-numeric columns return the first
      non-null value among duplicates).

    Example:
        # Data as list-of-lists
        data = [
            ["A", "B", "A"],
            [1, 10, 2],
            [3, 20, 4]
        ]
        df = sum_duplicate_headers(data)
        # result has columns: A, B with A summed (1+2, 3+4) per row

    Requires: pandas installed. If you want to use colmerge, install it;
    otherwise the function will use pandas-only fallback.
    """
    import pandas as pd

    # Normalize input to DataFrame
    if isinstance(table, pd.DataFrame):
        df = table.copy()
    elif isinstance(table, list):
        if len(table) == 0:
            return pd.DataFrame()
        # list of dicts?
        if all(isinstance(r, dict) for r in table):
            df = pd.DataFrame(table)
        # list-of-lists: first row is header
        elif all(isinstance(r, (list, tuple)) for r in table):
            header = table[0]
            rows = table[1:]
            df = pd.DataFrame(rows, columns=header)
        else:
            raise ValueError("If input is a list, it must be a list-of-dicts or list-of-lists (header first).")
    else:
        raise ValueError("Input must be a pandas.DataFrame, a list-of-dicts, or a list-of-lists (header first).")

    # Try to use colmerge if available
    try:
        import colmerge
        # Different versions of colmerge might expose different functions; try a couple of sensible names.
        if hasattr(colmerge, "merge_columns"):
            # hypothetical API: merge_columns(df, agg=...)
            try:
                return colmerge.merge_columns(df, agg="sum")
            except TypeError:
                return colmerge.merge_columns(df, agg=sum)
        if hasattr(colmerge, "merge"):
            # hypothetical API: merge(df, axis='columns', agg='sum')
            try:
                return colmerge.merge(df, axis="columns", agg="sum")
            except TypeError:
                return colmerge.merge(df, axis="columns", agg=sum)
        if hasattr(colmerge, "colmerge"):
            # try another possible entrypoint
            try:
                return colmerge.colmerge(df, agg="sum")
            except TypeError:
                return colmerge.colmerge(df, agg=sum)
        # If none of the above found, fall through to pandas fallback
    except Exception:
        # Any ImportError or usage error -> fallback to pandas
        pass

    # Pandas fallback implementation:
    # For each unique column name:
    #  - try to coerce duplicate columns to numeric; if any numeric values exist, sum numerically per row
    #  - otherwise, take first non-null (leftmost) value per row
    cols = list(df.columns)
    unique_cols = []
    seen = set()
    for c in cols:
        if c not in seen:
            unique_cols.append(c)
            seen.add(c)

    out = {}
    for name in unique_cols:
        # select all columns with this name (keeps original order)
        sub = df.loc[:, df.columns == name]
        # try numeric coercion
        sub_num = sub.apply(pd.to_numeric, errors="coerce")
        # If any numeric value exists anywhere in sub_num, compute numeric sum row-wise
        if sub_num.notna().any().any():
            # sum across columns, treating NaN as 0 when mixing with numeric values
            summed = sub_num.sum(axis=1, skipna=True)
            # If a row had all NaN in numeric coercion, summed will be 0. To preserve truly-all-NaN,
            # detect rows where all original entries were NaN or empty and set to NaN.
            all_nan_mask = sub_num.isna().all(axis=1)
            summed = summed.where(~all_nan_mask, other=pd.NA)
            out[name] = summed
        else:
            # non-numeric: choose first non-null value from the duplicate columns
            first_non_null = sub.bfill(axis=1).iloc[:, 0]
            out[name] = first_non_null

    result = pd.DataFrame(out, index=df.index)
    return result
