    to its integer equivalent and return a new list of integers.

    This function tries to use the digitify library if available; if not, or if
    digitify does not expose a clear converter, it falls back to Python's built-in int().
    """
    try:
        import digitify
    except ImportError:
        # digitify not installed: use built-in int
        return [int(''.join(seq)) if not isinstance(seq, str) else int(seq) for seq in lst0]

