        'convert', 'convert_to_int', 'intify'
    )
    for name in candidates:
        fn = getattr(digitify, name, None)
        if callable(fn):
            converter = fn
            break

    # Try a few likely class/container names if no function found
    if converter is None:
        for name in ('Digitify', 'Digitifier', 'Converter'):
            cls = getattr(digitify, name, None)
            if cls and callable(cls):
                converter = cls
                break

    def to_int_using_converter(seq):
        # Normalize seq to a string of digits
        s = seq if isinstance(seq, str) else ''.join(seq)
        if converter is None:
            return int(s)
