```python
from typing import Any, Union, Optional

def extract_column_slice(df0: Any,
                         start_column0: Union[int, str],
                         end_column0: Union[int, str]) -> Any:
    """
    Extract a contiguous slice of columns from a 2-D dataset df0, from
    start_column0 through end_column0 (inclusive).

    - If the optional 'dfslice' library is installed and exposes a reasonable
      slicing function, this tries to use it first.
    - Otherwise falls back to pandas / numpy behavior:
        * If df0 is a pandas DataFrame, returns a DataFrame using .iloc (preserving labels).
        * Otherwise treats df0 as array-like and returns a NumPy array.

    Parameters
    - df0: 2-D dataset (pandas.DataFrame or array-like)
    - start_column0: start column index (int) or column label (str)
    - end_column0: end column index (int) or column label (str). Inclusive.

    Returns
    - Sliced dataset (same container type where possible).

    Raises
    - ValueError for invalid start/end or if label not found.
    - TypeError if df0 is not 2-D-like.
    """
    # Try to use dfslice if available
    try:
        import dfslice  # type: ignore
    except Exception:
        dfslice = None

    # Helper to convert label to integer index for pandas-like objects
    def _label_to_index(obj, label):
        # If label is already int, return it
        if isinstance(label, int):
            return label
        # If it's a pandas-like object with columns attribute
        cols = getattr(obj, "columns", None)
        if cols is not None:
            try:
                # list(...) in case columns is an Index object
                return list(cols).index(label)
            except ValueError:
                raise ValueError(f"Column label not found: {label}")
        # If no columns attribute and label is not int, cannot resolve
        raise TypeError("Cannot resolve non-integer column label for this object")

    # If dfslice is present, attempt common dfslice calling patterns.
    if dfslice is not None:
        # Try common API patterns guarded by try/except so the fallback keeps working
        try:
            # Pattern 1: dfslice.slice(dataset, axis=1, start=..., end=...)
            if hasattr(dfslice, "slice"):
                try:
                    return dfslice.slice(df0, axis=1, start=start_column0, end=end_column0)
                except TypeError:
                    # maybe signature is different; try other patterns below
                    pass

            # Pattern 2: dfslice.slice_columns(df, start, end)
            if hasattr(dfslice, "slice_columns"):
                return dfslice.slice_columns(df0, start_column0, end_column0)

            # Pattern 3: dfslice.slice_array(array, axis, start, end)
            if hasattr(dfslice, "slice_array"):
                return dfslice.slice_array(df0, 1, start_column0, end_column0)

            # Pattern 4: dfslice.window or dfslice.view (generic names)
            if hasattr(dfslice, "window"):
                try:
                    return dfslice.window(df0, axis=1, start=start_column0, end=end_column0)
                except Exception:
                    pass
            if hasattr(dfslice, "view"):
                try:
                    return dfslice.view(df0, axis=1, start=start_column0, end=end_column0)
                except Exception:
                    pass
        except Exception:
            # Any unexpected error using dfslice -> fall back to pandas/numpy below
            pass

    # Fallback: handle pandas DataFrame if available
    try:
        import pandas as pd  # type: ignore
    except Exception:
        pd = None

    if pd is not None and isinstance(df0, pd.DataFrame):
        # Resolve start/end to integer positions if labels supplied
        start_idx = _label_to_index(df0, start_column0)
        end_idx = _label_to_index(df0, end_column0)
        if start_idx < 0 or end_idx < 0:
            raise ValueError("start/end column indices must be non-negative")
        if start_idx > end_idx:
            raise ValueError("start_column0 must be <= end_column0")
        # .iloc is end-exclusive, so use end_idx + 1
        return df0.iloc[:, start_idx : end_idx + 1]

    # Final fallback: treat as array-like using numpy
    try:
        import numpy as np  # type: ignore
    except Exception:
        np = None

    if np is None:
        raise RuntimeError("Neither dfslice nor pandas nor numpy are available to perform slicing")

    arr = np.asarray(df0)
    if arr.ndim != 2:
        raise TypeError("df0 must be two-dimensional (ndim == 2)")

    # Convert start/end to integers (labels are not supported for raw arrays)
    if not isinstance(start_column0, int):
        raise TypeError("For array-like df0, start_column0 must be an integer index")
    if not isinstance(end_column0, int):
        raise TypeError("For array-like df0, end_column0 must be an integer index")

    s = int(start_column0)
    e = int(end_column0)
    if s < 0 or e < 0 or s > e or e >= arr.shape[1]:
        raise IndexError("Invalid start/end column indices for array shape")

    # numpy slicing is end-exclusive, so use e + 1
    return arr[:, s : e + 1]
```

