from typing import Any, Dict
import pandas as pd
import df2dict

def df0_to_dict(df0: pd.DataFrame, row_id: str = "var0") -> Dict[Any, Dict[str, Any]]:
    """
    Convert a 2D table (pandas DataFrame) `df0` into a dictionary mapping each
    identifier in column `row_id` to that row's data (as a dict of column:value).

    Uses the df2dict library when available; falls back to pandas' to_dict if needed.

    Parameters:
    - df0: pandas.DataFrame - input table
    - row_id: str - name of the column in df0 to use as the dictionary keys (default "var0")

    Returns:
    - dict mapping identifier -> {column: value, ...}

    Example:
    >>> import pandas as pd
    >>> df0 = pd.DataFrame({'var0': ['a','b'], 'x': [1,2], 'y': [3,4]})
    >>> df0_to_dict(df0)
    {'a': {'x': 1, 'y': 3}, 'b': {'x': 2, 'y': 4}}
    """
    if not isinstance(df0, pd.DataFrame):
        raise TypeError("df0 must be a pandas DataFrame")

    if row_id not in df0.columns:
        raise KeyError(f"Column '{row_id}' not found in df0")

    # Make the requested column the index so that conversion produces keys from it
    df_indexed = df0.set_index(row_id)

    # Try common df2dict API names; pass orient='index' if accepted.
    try_functions = ("df2dict", "to_dict", "convert", "convert_df", "dataframe_to_dict")

    for fname in try_functions:
        func = getattr(df2dict, fname, None)
        if callable(func):
            try:
                # try with orient argument first (common expectation)
                return func(df_indexed, orient="index")
            except TypeError:
                # try without orient argument
                try:
                    return func(df_indexed)
                except Exception:
                    # If this function fails, try next available
                    continue
            except Exception:
                continue

    # If df2dict did not provide a usable callable, fallback to pandas' to_dict
    return df_indexed.to_dict(orient="index")
