# Self-contained function that uses the `round_ops` library to apply floor or ceiling
# to every element of a numeric collection.
# Supports Python scalars, lists, tuples, numpy arrays and pandas Series (if numpy/pandas installed).

from typing import Any
import round_ops

def apply_round_collection(var0: Any, str0: str) -> Any:
    """
    Apply either floor or ceiling operation to each element in a numeric collection var0
    based on the operation specified in str0.

    Parameters
    - var0: A numeric value or an iterable collection of numeric values (list, tuple,
            numpy.ndarray, pandas.Series, etc.).
    - str0: Operation to apply. Accepts "floor", "ceiling", or "ceil" (case-insensitive).

    Returns
    - A value or collection of the same logical type as var0 with the operation applied elementwise.

    Raises
    - ValueError: if str0 does not specify a supported operation.
    - Any exception propagated from the underlying operations (e.g., when elements are not numeric).
    """
    if not isinstance(str0, str):
        raise ValueError("str0 must be a string specifying 'floor' or 'ceiling'")

    op_key = str0.strip().lower()
    if op_key in ("floor",):
        op = round_ops.floor
    elif op_key in ("ceiling", "ceil"):
        op = round_ops.ceil
    else:
        raise ValueError("Unsupported operation in str0. Use 'floor' or 'ceiling' (or 'ceil').")

    # Attempt to detect numpy and pandas types if available
    np = None
    pd = None
    try:
        import numpy as np  # type: ignore
    except Exception:
        np = None
    try:
        import pandas as pd  # type: ignore
    except Exception:
        pd = None

    # Scalars: apply directly
    if not hasattr(var0, "__iter__") or isinstance(var0, (str, bytes)):
        return op(var0)

    # numpy array: try direct call, fallback to vectorize if needed
    if np is not None and isinstance(var0, np.ndarray):
        try:
            return op(var0)
        except Exception:
            vec = np.vectorize(op)
            return vec(var0)

    # pandas Series: try direct call, fallback to map/apply
    if pd is not None and isinstance(var0, pd.Series):
        try:
            return op(var0)
        except Exception:
            return var0.map(op)

    # For other iterables (lists, tuples, generators, sets, etc.)
    # preserve type for list/tuple, otherwise return a list
    try:
        # Special-case generator: consume it
        if not hasattr(var0, "__len__") and hasattr(var0, "__iter__"):
            seq = list(var0)
        else:
            seq = var0
    except Exception:
        # Fallback: try to iterate
        seq = list(var0)

    # Apply operation elementwise
    result_iter = [op(x) for x in seq]

    # Preserve common container types
    if isinstance(seq, tuple):
        return tuple(result_iter)
    if isinstance(seq, list):
        return result_iter
    # For sets, return a set (note: order and duplicates lost)
    if isinstance(seq, set):
        return set(result_iter)
    # Default: return list
    return result_iter
