            if isinstance(x, (list, tuple)):
                # if tuple shorter than expected, return None for missing elements
                return x[idx] if idx < len(x) else None
            # if it's a 2-element scalar-like (unlikely), try to index
            try:
                return x[idx]
            except Exception:
                return None
        except Exception:
            return None

    s0 = df["var0"].apply(lambda x: _get_elem(x, 0))
    s1 = df["var0"].apply(lambda x: _get_elem(x, 1))

    df[new_column_names[0]] = s0
    df[new_column_names[1]] = s1

    if drop_original and "var0" in df.columns:
