```python
from typing import Any, Callable, Iterable, List, Mapping, Sequence, Tuple, Union
import operator
import importlib

def conditional_column_sum(
    dataset: Union[str, Sequence[Mapping[str, Any]], "pandas.DataFrame"],
    column: Union[str, int],
    condition: Union[Callable[[Mapping[str, Any]], bool],
                     Mapping[str, Any],
                     Tuple[str, str, Any],
                     str],
) -> Union[int, float]:
    """
    Sum values in `column` for rows that satisfy `condition`.

    Parameters:
    - dataset: a pandas.DataFrame, a list of dict-like records, or a path to a CSV file (string).
    - column: column name (str) or index (int).
    - condition:
        * callable: function(row) -> bool, where row is a mapping (dict-like) with column keys
        * dict: all key==value conditions must hold (equality)
        * tuple: (field, operator, value) where operator in ("==","!=" , ">",">=", "<","<=","in","not in")
        * str: a Python expression evaluated with `row` variable (e.g. "row['age']>30")

    Returns:
    - sum (int or float) of the column values for rows satisfying the condition.

    Uses the `condsum` library if available (attempts to call a plausible API). If condsum is
    unavailable or doesn't provide a compatible function, falls back to an internal implementation.
    """

    # Helper: load dataset into list of dict-like rows
    rows = None
    try:
        import pandas as _pd
    except Exception:
        _pd = None

    # If dataset is a path to CSV
    if isinstance(dataset, str):
        if _pd is not None:
            rows = _pd.read_csv(dataset).to_dict(orient="records")
        else:
            # Basic CSV reader fallback (no pandas)
            import csv
            with open(dataset, newline='', encoding='utf-8') as f:
                reader = csv.DictReader(f)
                rows = [dict(r) for r in reader]
    else:
        # If user passed a pandas DataFrame
        try:
            import pandas as _pd2
            if _pd2 is not None and isinstance(dataset, _pd2.DataFrame):
                rows = dataset.to_dict(orient="records")
        except Exception:
            pass

    # If still not set, assume it's a sequence of mappings (list of dicts)
    if rows is None:
        # If it's a sequence of mappings, shallow copy to list
        if isinstance(dataset, Sequence):
            rows = list(dataset)  # may be list of dicts or list of objects supporting mapping access
        else:
            # try to iterate
            rows = list(dataset)

    # Normalise column lookup: for mapping rows we expect column to be a key (str)
    # If column is an int, we will try to treat rows as sequences or get nth value from ordered keys.
    def get_value_from_row(r, col):
        # If mapping and col in keys:
        if isinstance(r, Mapping):
            if isinstance(col, int):
                # try to access by positional index over the mapping's keys (stable order in Py3.7+)
                try:
                    key = list(r.keys())[col]
                    return r.get(key)
                except Exception:
                    # fall back to None
                    return None
            else:
                return r.get(col)
        else:
            # If row is a sequence (list/tuple) and col is int
            try:
                if isinstance(col, int):
                    return r[col]
                else:
                    # If row is an object with attributes
                    return getattr(r, col)
            except Exception:
                return None

    # Build predicate function from the provided condition argument
    if callable(condition):
        predicate = condition
    elif isinstance(condition, Mapping):
        # all equality checks
        def predicate(r, cond=condition):
            for k, v in cond.items():
                if isinstance(r, Mapping):
                    if r.get(k) != v:
                        return False
                else:
                    # try attribute
                    if getattr(r, k, None) != v:
                        return False
            return True
    elif isinstance(condition, (tuple, list)) and len(condition) == 3:
        field, op_str, value = condition
        ops = {
            "==": operator.eq,
            "!=": operator.ne,
            ">": operator.gt,
            ">=": operator.ge,
            "<": operator.lt,
            "<=": operator.le,
            "in": lambda a, b: a in b,
            "not in": lambda a, b: a not in b,
        }
        if op_str not in ops:
            raise ValueError(f"Unsupported operator: {op_str}")

        comp = ops[op_str]

        def predicate(r, field=field, comp=comp, value=value):
            v = r.get(field) if isinstance(r, Mapping) else getattr(r, field, None)
            try:
                return comp(v, value)
            except Exception:
                return False
    elif isinstance(condition, str):
        # condition is a Python expression evaluated with 'row' variable.
        # Example: "row['age'] > 30 and row['status']=='active'"
        expr = condition
        # Create a lambda that evaluates the expression with row in local namespace.
        def predicate(r, expr=expr):
            # Limit builtins exposure
            local_vars = {"row": r}
            try:
                return bool(eval(expr, {"__builtins__": {}}, local_vars))
            except Exception:
                # If evaluation failed, return False
                return False
    else:
        raise ValueError("Unsupported condition type. See docstring for allowed types.")

    # Attempt to use condsum library if installed
    try:
        condsum = importlib.import_module("condsum")
        # Try several plausible function names that condsum might provide.
        for fname in ("conditional_sum", "condsum", "sum_if", "conditionalSum", "sum_conditional"):
            func = getattr(condsum, fname, None)
            if callable(func):
                # Try calling it. We'll pass rows (list of dicts), column, and a predicate if accepted.
                try:
                    # Many libs expect a predicate or condition representation; try calling with predicate first.
                    return func(rows, column, predicate)
                except TypeError:
                    # Maybe func expects (rows, column, condition) where condition is user-provided raw condition.
                    try:
                        return func(rows, column, condition)
                    except Exception:
                        # last resort: maybe the API expects (rows, condition, column)
                        try:
                            return func(rows, condition, column)
                        except Exception:
                            # cannot call this function compatibly; continue searching
                            continue
        # If condsum exists but we couldn't find a callable API we can use, fall back to local implementation.
    except Exception:
        # condsum not installed or import error -> fall back
        pass

    # Pure-Python fallback implementation
    total = 0
    any_int = True
    any_float = False
    for row in rows:
        try:
            ok = predicate(row)
        except Exception:
            ok = False
        if not ok:
            continue
        val = get_value_from_row(row, column)
        # Attempt to convert numeric-like strings
        if val is None:
            continue
        try:
            # keep integers as int where possible
            if isinstance(val, bool):
                # Treat bool as numeric? Usually not; convert to int if needed:
                num = int(val)
            elif isinstance(val, int):
                num = val
            elif isinstance(val, float):
                num = val
            elif isinstance(val, str):
                # strip and try parse int then float
                s = val.strip()
                if s == "":
                    continue
                if s.isdigit() or (s.startswith("-") and s[1:].isdigit()):
                    num = int(s)
                else:
                    num = float(s)
            else:
                # try numeric conversion
                num = float(val)
        except Exception:
            # skip non-numeric values
            continue

        # track whether ints only
        if isinstance(num, float):
            any_float = True
        if not isinstance(num, int):
            any_int = False

        total += num

    # Return int if all ints, else float
    if any_float:
        return float(total)
    else:
        return int(total)
