def map_var0_to_var1(table1, table2):
    """
    Return a dict mapping row[var0] from table1 -> row[var1] from table2
    for rows where table1.col0 == table2.col0.

    Parameters
    ----------
    table1, table2 : list[dict] or dict[str, list]
        The tables. Each must include at least:
          - table1: columns "col0" and "var0"
          - table2: columns "col0" and "var1"

    Returns
    -------
    dict
        Mapping { var0_value_from_table1: var1_value_from_table2 } for all matching col0 rows.

    Notes
    -----
    - The function will attempt to use the `coljoin` library's join if available.
      If not available or usable, a pure-Python join is performed.
    - If there are multiple rows in table2 with the same col0, the last encountered var1 wins.
    - If rows in table1 have the same var0, later ones overwrite earlier mappings.
    """
    # helper: normalize both table representations to list-of-dicts (rows)
    def normalize(table):
        if isinstance(table, dict):
            # column-oriented dict-of-lists => convert to list of row dicts
            if not table:
                return []
            lengths = [len(v) for v in table.values()]
            if not lengths:
                return []
            # basic sanity: all columns must have same length
            if not all(l == lengths[0] for l in lengths):
                raise ValueError("All columns in column-oriented table must have the same length.")
            n = lengths[0]
            keys = list(table.keys())
            return [{k: table[k][i] for k in keys} for i in range(n)]
        elif isinstance(table, list):
            # assume list of dicts (rows)
            if not table:
                return []
            if not isinstance(table[0], dict):
                raise ValueError("Unsupported list format: expected list of dict rows.")
            return table
        else:
            raise ValueError("Unsupported table format. Use list-of-dicts or dict-of-lists.")

    rows1 = normalize(table1)
    rows2 = normalize(table2)

    # helper: safe extractor for a column name in a joined row (handles possible renaming by join impl)
    def extract_col(row, colname):
        if colname in row:
            return row[colname]
        # try several plausible suffix/pattern matches (e.g. "left.var0", "var0_left", etc.)
        for k in row:
            if k.endswith(colname) or k.endswith("_" + colname) or k.endswith("." + colname) or colname in k:
                return row[k]
        return None

    # Try to use coljoin.join (if installed). If not available or fails, fallback to manual join.
    joined_rows = None
    try:
        import coljoin
        # many simple coljoin APIs provide a join(...) function; try common signatures.
        try:
            # try the common signature: join(left, right, left_on=..., right_on=..., how=...)
            joined_rows = coljoin.join(rows1, rows2, left_on="col0", right_on="col0", how="inner")
        except Exception:
            # some versions might expose a function named 'inner_join' or similar
            try:
                joined_rows = coljoin.inner_join(rows1, rows2, left_on="col0", right_on="col0")
            except Exception:
                # give up on coljoin use and fall back
                joined_rows = None
    except Exception:
        joined_rows = None

    result = {}

    if joined_rows is not None:
        # build mapping from joined rows
        for r in joined_rows:
            v0 = extract_col(r, "var0")
            v1 = extract_col(r, "var1")
            # Only include if both values found
            if v0 is not None and v1 is not None:
                result[v0] = v1
        return result

    # Fallback manual inner join (efficient approach: index table2 by col0)
    index2 = {}
    for r in rows2:
        if "col0" in r and "var1" in r:
            index2[r["col0"]] = r["var1"]

    for r in rows1:
        if "col0" in r and "var0" in r:
            key_col0 = r["col0"]
            if key_col0 in index2:
                result[r["var0"]] = index2[key_col0]

    return result

