    pandas.DataFrame
        A new DataFrame with columns whose names start with 'Unnamed' removed.
    """
    import pandas as pd

    # Ensure df0 is a DataFrame (or convertible to one)
    if not isinstance(df0, pd.DataFrame):
        try:
            df0 = pd.DataFrame(df0)
        except Exception as e:
            raise TypeError("df0 must be a pandas DataFrame or convertible to one") from e

    # Try to use df_unnamed_cleaner if available and exposes a callable
    try:
        import df_unnamed_cleaner
    except Exception:
