                    pass
                # If result is a simple truthy value or unexpected, fall back
                break  # stop trying other names and use pandas fallback

    # fallback to pandas implementation
    try:
        return _pandas_missing_columns(df)
    except Exception:
        # as ultimate fallback, return empty list
        return []
