def filter_non_empty(lst0):
    """
    Return a new collection containing only the elements from lst0 that are not empty.
    Uses the `listclean` library when available; otherwise falls back to a local implementation.

    Emptiness definition used by the fallback:
      - None is considered empty
      - Objects with a length (len(obj)) equal to 0 are considered empty
      - Numeric types and booleans are NOT considered empty (so 0 and False are kept)

    The function will try to preserve the input collection type for common types
    (list, tuple, set, dict). For other iterable types it will attempt to reconstruct
    the same type; if that fails it returns a list.
    """
    try:
        import listclean
    except Exception:
        listclean = None

    # If listclean exposes a standard function to remove empties, try to use it.
    if listclean is not None:
        for fname in ("remove_empty", "compact", "clean", "drop_empty", "filter_nonempty", "filter_empty"):
            func = getattr(listclean, fname, None)
            if callable(func):
                try:
                    return func(lst0)
                except TypeError:
                    # some variants may accept inplace or other kwargs
                    try:
                        return func(lst0, inplace=False)
                    except Exception:
                        continue
                except Exception:
                    # if listclean fails for unexpected reasons, fall back
                    break

    # Fallback local implementation
    def _is_empty(x):
        if x is None:
            return True
        # preserve booleans and numbers (0, False are not "empty")
        if isinstance(x, bool):
            return False
        if isinstance(x, (int, float, complex)):
            return False
        try:
            return len(x) == 0
        except Exception:
            # objects without length are treated as non-empty by default
            return False

    # Dict: filter by value emptiness
    if isinstance(lst0, dict):
        return type(lst0)((k, v) for k, v in lst0.items() if not _is_empty(v))

    # List, tuple, set
    if isinstance(lst0, list):
        return [e for e in lst0 if not _is_empty(e)]
    if isinstance(lst0, tuple):
        return tuple(e for e in lst0 if not _is_empty(e))
    if isinstance(lst0, set):
        return type(lst0)(e for e in lst0 if not _is_empty(e))

    # Generic iterable: try to reconstruct same type, else return list
    try:
        return type(lst0)(e for e in lst0 if not _is_empty(e))
    except Exception:
        return [e for e in lst0 if not _is_empty(e)]

