def rename_with_colmapper(df0, lst0):
    """
    Rename columns of df0 according to mapping pairs in lst0, using colmapper if available.

    Parameters
    - df0: pandas.DataFrame
    - lst0: dict mapping old_name -> new_name OR iterable of (old_name, new_name) pairs

    Returns
    - A new pandas.DataFrame with columns renamed.

    Behavior:
    - If the `colmapper` library is installed and exposes a usable API, the function will try to
      use it to perform the rename. If that fails or colmapper is not available, pandas.DataFrame.rename
      is used as a fallback.
    """
    import pandas as pd

    # Validate df0
    if not isinstance(df0, pd.DataFrame):
        raise TypeError("df0 must be a pandas DataFrame")

    # Convert lst0 to a dict mapping
    if isinstance(lst0, dict):
        mapping = dict(lst0)
    else:
        try:
            mapping = dict(lst0)
        except Exception:
            raise ValueError("lst0 must be a dict or an iterable of (old_name, new_name) pairs")

    # Try to use colmapper if available
    try:
        import colmapper as cm  # attempt to import colmapper
    except Exception:
        cm = None

    if cm is not None:
        # Try a few likely colmapper function names and call signatures
        tried = []
        for fn_name in ('rename', 'rename_columns', 'map', 'map_columns', 'apply', 'transform'):
            if hasattr(cm, fn_name):
                fn = getattr(cm, fn_name)
                tried.append(fn_name)
                # Try common call signatures: fn(df, mapping) or fn(mapping, df)
                for args in ((df0, mapping), (mapping, df0)):
                    try:
                        result = fn(*args)
                        # If a DataFrame-like result is produced, return it
                        if isinstance(result, pd.DataFrame):
                            return result
                        # some APIs might modify in place and return None -> return df0.copy()
                        if result is None:
                            return df0.rename(columns=mapping)
                    except TypeError:
                        # function signature mismatch; try next signature/name
                        continue
                    except Exception:
                        # underlying call failed; try next possibility
                        continue

        # Try a Column/ColMapper class pattern if present
        Cls = getattr(cm, 'ColMapper', None) or getattr(cm, 'ColumnMapper', None)
        if Cls is not None:
            try:
                mapper = Cls(mapping)
                # try common methods on mapper
                if hasattr(mapper, 'transform'):
                    out = mapper.transform(df0)
                    if isinstance(out, pd.DataFrame):
                        return out
                elif callable(mapper):
                    out = mapper(df0)
                    if isinstance(out, pd.DataFrame):
                        return out
            except Exception:
                # fall back to pandas
                pass

    # Fallback: use pandas.rename
    return df0.rename(columns=mapping)
