      (e.g. moving_average, simple_moving_average, sma). If none succeed, uses
      an efficient cumulative-sum fallback.
    - Converts the result to a plain Python list before returning.

    Example:
      moving_average_sequence([1,2,3,4,5], 3)  -> [2.0, 3.0, 4.0]
    """
    # basic validation
    if not isinstance(window_size, int) or window_size <= 0:
        raise ValueError("window_size must be a positive integer")
    try:
        n = len(lst0)
    except TypeError:
        raise TypeError("lst0 must be a sequence with a length (e.g., list, tuple, numpy array)")

    # try using the moving_average library if present
    try:
        import moving_average as _ma  # attempt to import the requested library
    except Exception:
        _ma = None

    if _ma is not None:
        # try a few likely function names and call patterns
        candidates = [
            "moving_average", "simple_moving_average", "simple", "sma", "ma",
            "movingavg", "moving_average_simple", "movingAverage"
        ]
        for name in candidates:
            fn = getattr(_ma, name, None)
            if callable(fn):
                try:
                    result = fn(lst0, window_size)
                    return list(result)
                except TypeError:
                    # try keyword argument if positional failed
                    try:
                        result = fn(lst0, window_size=window_size)
                        return list(result)
                    except Exception:
                        continue
                except Exception:
                    continue
        # if the module itself is callable, try calling it
        if callable(_ma):
            try:
                return list(_ma(lst0, window_size))
            except Exception:
                pass
        # if we got here, the library is present but we couldn't call a known API;
        # fall through to the local implementation

    # fallback local implementation using cumulative sums (O(n))
    if window_size > n:
        return []  # no complete windows

    # convert to floats for safe division; this will raise if elements are non-numeric
    arr = [float(x) for x in lst0]

    cumsum = [0.0] * (n + 1)
    for i in range(n):
        cumsum[i + 1] = cumsum[i] + arr[i]

    out_len = n - window_size + 1
    result = [(cumsum[i + window_size] - cumsum[i]) / window_size for i in range(out_len)]
    return result

