            if callable(func):
                try:
                    it = func(pattern, var0, flags) if flags else func(pattern, var0)
                    last = None
                    for m in it:
                        last = m
                    if last is not None:
                        return _build_from_matchobj(last)
                except Exception:
                    pass

    # Fallback to stdlib re module if regex_last not usable or didn't produce result
    import re
    try:
        last_match = None
        for m in re.finditer(pattern, var0, flags):
            last_match = m
        return _build_from_matchobj(last_match)
    except re.error:
        # invalid pattern
        return None

