                if results:
                    return sorted(results, key=lambda x: x[0])
        except Exception:
            # fall through to other attempts
            pass

        # 2) MultiFind / Finder class style (common variants)
        for cls_name in ("MultiFind", "MultiFinder", "Finder", "AhoCorasick"):
            if hasattr(multifind, cls_name):
                cls = getattr(multifind, cls_name)
                try:
                    # Try constructing with patterns and a case flag, then search
                    try:
                        mf = cls([str0], case_sensitive=False)
                    except TypeError:
                        # try without flags
                        mf = cls([str0])
                    # Try a few common search methods
                    for method in ("find_all", "finditer", "search", "scan"):
                        if hasattr(mf, method):
                            res = getattr(mf, method)(var0)
                            # Normalize results
                            for item in res:
                                if hasattr(item, "span"):
                                    s, e = item.span()
                                    results.append((s, e, var0[s:e]))
                                elif isinstance(item, tuple):
                                    if len(item) >= 2:
                                        s, e = item[0], item[1]
                                        matched = item[2] if len(item) >= 3 else var0[s:e]
                                        results.append((s, e, matched))
                                    elif len(item) == 1 and isinstance(item[0], int):
                                        s = item[0]; e = s + len(str0)
