def weighted_average_from_table(table, col_values, col_weights):
    """
    Compute the weighted average of the entries in column `col_values` using the
    corresponding weights in column `col_weights` from a tabular dataset.
    This function will try to use the `weighted_avg_table` library if available;
    if not present or it doesn't expose a recognized API, the function falls back
    to a robust pure-Python implementation.

    Parameters
    - table: tabular dataset in one of these forms:
        * pandas.DataFrame
        * list of dicts (each dict is a row)
        * list of lists (optionally first row can be header)
        * iterable of tuples/lists (with column indices used for col_* when ints given)
    - col_values: column name (str) or column index (int) for values
    - col_weights: column name (str) or column index (int) for weights

    Returns
    - float: weighted average (value) if at least one positive/nonzero weight exists
    - None: if no valid (numeric) pairs found or total weight is zero
    """
    import math

    # Try to use weighted_avg_table library if available.
    try:
        import weighted_avg_table as wat
    except Exception:
        wat = None

    # If the library exposes a simple API, try to use it.
    if wat is not None:
        # common sensible API names to try
        try_names = [
            ("weighted_avg", (table, col_values, col_weights)),
            ("weighted_average", (table, col_values, col_weights)),
            ("compute_weighted_avg", (table, col_values, col_weights)),
        ]
        for name, args in try_names:
            fn = getattr(wat, name, None)
            if callable(fn):
                try:
                    return fn(*args)
                except Exception:
                    # if that API exists but failed, continue to fallback
                    break
        # try a class-style API
        WClass = getattr(wat, "WeightedAvgTable", None) or getattr(wat, "WeightedAverageTable", None)
        if WClass is not None:
            try:
                # try common factory or constructor patterns
                if hasattr(WClass, "from_table"):
                    obj = WClass.from_table(table)
                else:
                    obj = WClass(table)
                # try common compute method names
                for mname in ("compute", "compute_weighted_avg", "weighted_average", "result"):
                    m = getattr(obj, mname, None)
                    if callable(m):
                        try:
                            return m(col_values, col_weights)
                        except TypeError:
                            # some APIs may take (value_col, weight_col) or none; try both
                            try:
                                return m()
                            except Exception:
                                pass
                # if no working method found, fall back to manual
            except Exception:
                # fall back to manual
                pass

    # Fallback: robust manual implementation that handles common table types.
    def is_number(x):
        try:
            # treat booleans as non-numeric for this use-case
            if isinstance(x, bool):
                return False
            xf = float(x)
            return not (math.isnan(xf) or math.isinf(xf))
        except Exception:
            return False

    # Iterator over (value, weight) pairs
    def rows_from_table(tab):
        # pandas DataFrame
        try:
            import pandas as pd
        except Exception:
            pd = None

        if pd is not None and isinstance(tab, pd.DataFrame):
            for _, row in tab.iterrows():
                val = row[col_values] if (not isinstance(col_values, int)) else row.iat[col_values]
                wt = row[col_weights] if (not isinstance(col_weights, int)) else row.iat[col_weights]
                yield val, wt
            return

        # list/iterable of dicts
        if isinstance(tab, (list, tuple)):
            if len(tab) == 0:
                return
            # detect list of dicts
            if isinstance(tab[0], dict):
                for r in tab:
                    yield r.get(col_values) if not isinstance(col_values, int) else r.get(col_values), \
                          r.get(col_weights) if not isinstance(col_weights, int) else r.get(col_weights)
                return
            # detect header row (list of lists with header as first row of strings)
            if isinstance(tab[0], (list, tuple)) and all(isinstance(c, str) for c in tab[0]):
                header = list(tab[0])
                value_idx = col_values if isinstance(col_values, int) else (header.index(col_values) if col_values in header else None)
                weight_idx = col_weights if isinstance(col_weights, int) else (header.index(col_weights) if col_weights in header else None)
                if value_idx is None or weight_idx is None:
                    # header names not found; no rows
                    return
                for row in tab[1:]:
                    yield (row[value_idx] if value_idx < len(row) else None,
                           row[weight_idx] if weight_idx < len(row) else None)
                return
            # otherwise assume list/iterable of sequences (no header) or tuples
            # treat col_* as indices (must be ints)
            if isinstance(col_values, int) and isinstance(col_weights, int):
                for row in tab:
                    try:
                        yield row[col_values], row[col_weights]
                    except Exception:
                        yield None, None
                return
            # if columns given as names but rows are sequences, cannot resolve
        # as a last resort, try to iterate and yield nothing
        return

    weighted_sum = 0.0
    total_weight = 0.0
    found_any = False

    for val, wt in rows_from_table(table):
        # Normalize and validate numbers
        if not is_number(wt) or not is_number(val):
            continue
        fv = float(val)
        fw = float(wt)
        # skip zero or negative weights? Typically weights can be zero but negative weights are unusual.
        # We'll include zero weights (they contribute nothing) and allow negative weights (mathematically valid).
        # However if fw == 0, it simply won't change the totals.
        weighted_sum += fv * fw
        total_weight += fw
        found_any = True

    if not found_any or total_weight == 0:
        return None

    return weighted_sum / total_weight

