from collections.abc import Mapping
from typing import Iterable, Any

def filter_by_keys(container: Mapping, keys: Iterable[Any]):
    """
    Return a new key-value container (mapping) that includes only the pairs
    whose keys appear in `keys`.

    Behavior:
    - If a module named `keyfilter` is importable and provides a `keyfilter`
      function, that will be used.
    - Otherwise, if `toolz.keyfilter` is available, that will be used.
    - Otherwise, a pure-Python fallback is used.
    - Preserves the input mapping type when possible (e.g., dict, OrderedDict).

    Args:
        container: A mapping (e.g. dict, OrderedDict) to filter.
        keys: An iterable of keys to keep.

    Returns:
        A new mapping of the same type as `container` (when possible) with only
        the selected key/value pairs.
    """
    key_set = set(keys)

    # Try to use a keyfilter-style function if available.
    try:
        import keyfilter as kf  # preferred per your request
        # common signature: keyfilter(predicate, mapping) where predicate takes key
        if hasattr(kf, 'keyfilter'):
            return kf.keyfilter(lambda k: k in key_set, container)
        # Some variants expose other names
        if hasattr(kf, 'filter'):
            # try function that accepts (predicate, mapping)
            try:
                return kf.filter(lambda k: k in key_set, container)
            except TypeError:
                # some libs expect predicate signature (k, v)
                return kf.filter(lambda k, v: k in key_set, container)
    except Exception:
        pass

    # Try toolz.keyfilter if available (common alternative)
    try:
        from toolz import keyfilter as tz_keyfilter
        return tz_keyfilter(lambda k: k in key_set, container)
    except Exception:
        pass

    # Fallback: pure-Python implementation
    if isinstance(container, dict):
        return {k: v for k, v in container.items() if k in key_set}

    if isinstance(container, Mapping):
        # Attempt to construct same mapping type from filtered items
        try:
            return type(container)((k, v) for k, v in container.items() if k in key_set)
        except Exception:
            # If that fails, return a plain dict
            return {k: v for k, v in container.items() if k in key_set}

    # If container is not a Mapping, try to treat it as an iterable of (k, v) pairs
    try:
        return type(container)((k, v) for k, v in container if k in key_set)
    except Exception:
        # Final fallback: return a dict
        return {k: v for k, v in container if k in key_set}
