        try:
            rows = list(df0)
        except Exception:
            rows = None

    if rows is None:
        raise TypeError("Could not extract rows from df0. Provide a pandas.DataFrame, "
                        "an iterable of row mappings/objects, or a tablefix table-like object.")

    # Helper to get the value of column var0 from a row
    def _get_val(row):
        # dict-like
        if isinstance(row, dict):
            return row.get(var0)
        # try item access (row[var0])
        try:
            return row[var0]
        except Exception:
            pass
        # try attribute access (row.var0)
        try:
            return getattr(row, var0)
        except Exception:
            pass
        # not able to extract the column
        raise ValueError(f"Cannot extract column '{var0}' from row of type {type(row)}")

    # Filter rows (keep those not equal to var1)
    filtered_rows = [r for r in rows if _get_val(r) != var1]

    # Reset indices:
    # - For list-of-dicts / list-of-rows, the list index is already consecutive.
    # - Try to mutate df0 in-place if it supports clear/extend or set_rows.
    try:
        if hasattr(df0, "clear") and hasattr(df0, "extend"):
            # clear and extend (e.g., list-like containers)
            df0.clear()
            df0.extend(filtered_rows)
            return df0
        if hasattr(df0, "set_rows") and callable(getattr(df0, "set_rows")):
            # some table implementations expose set_rows
            df0.set_rows(filtered_rows)
            return df0
        if hasattr(df0, "rows") and isinstance(df0.rows, list):
            # try mutate .rows attribute
            df0.rows[:] = filtered_rows
            return df0
    except Exception:
        # fall through to constructing a new table
        pass

    # If tablefix provides a Table class, try to construct a new tablefix.Table
    TableClass = getattr(tablefix, "Table", None)
    if TableClass is not None:
        try:
            # attempt simple constructor signature Table(rows)
            new_table = TableClass(filtered_rows)
            return new_table
        except Exception:
            # try Table.from_rows if available
            from_rows = getattr(TableClass, "from_rows", None)
            if callable(from_rows):
                try:
                    return TableClass.from_rows(filtered_rows)
                except Exception:
                    pass

    # As a last resort, if the original object was a plain list, return the new list
    if isinstance(df0, list):
        return filtered_rows

    # Otherwise return the filtered rows list (caller can reconstruct as needed)
