def lowercase_mapping(input_map):
    """
    Convert all keys and values in an input mapping to lowercase.

    Args:
        input_map (dict): A dictionary with string keys and values

    Returns:
        dict: A new dictionary with all keys and values converted to lowercase

    Example:
        >>> result = lowercase_mapping({'Name': 'John', 'CITY': 'NEW YORK'})
        >>> result
        {'name': 'john', 'city': 'new york'}
    """
    return dict(
        (key.lower(), value.lower() if isinstance(value, str) else value)
        for key, value in input_map.items()
    )


