    try:
        import datetimeify as dtfy
    except Exception:
        dtfy = None

    import pandas as pd
    try:
        import xarray as xr
    except Exception:
        xr = None

    # Helper to apply a parser (vectorized if possible)
    def _apply_parser(series_like):
        # Try to use datetimeify API if available
        if dtfy is not None:
            # common candidate names in datetimeify-like libraries
            for name in ('datetimeify', 'to_datetime', 'parse', 'parse_datetime'):
                fn = getattr(dtfy, name, None)
                if callable(fn):
                    try:
                        # Try passing a DataFrame/Series/array directly
                        if fmt is not None:
                            return fn(series_like, format=fmt)
                        else:
                            return fn(series_like)
                    except TypeError:
